        lsl     r10, r2, #31
        tst     r0, #2
        it      eq
        orreq   r10, r10, #1
        ubfx    r2, r0, #6, #1
        strb    r2, [r4, #CPU_V]
        ubfx    r2, r0, #5, #1
        strb    r2, [r4, #CPU_MF]
