        strb    r2, [r4, #CPU_C]
        tst     r0, #0x10
        itt     ne
        uxtbne  r8, r8
        uxtbne  r9, r9
        ubfx    r2, r0, #4, #2
        movw    r3, #:lower16:sa1e_tab
        movt    r3, #:upper16:sa1e_tab
